using System.Text; using InventorySystem.Application.Interfaces; using InventorySystem.Domain.Entities; using InventorySystem.Infrastructure.Persistence; using InventorySystem.Infrastructure.Services; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Configuration; using Microsoft.Extensions.DependencyInjection; using Microsoft.IdentityModel.Tokens;
namespace InventorySystem.Infrastructure;
public static class DependencyInjection { public static IServiceCollection AddInfrastructure(this IServiceCollection s,IConfiguration c){ s.AddDbContext<AppDbContext>(o=>o.UseSqlServer(c.GetConnectionString("DefaultConnection"))); s.AddScoped<IAppDbContext>(x=>x.GetRequiredService<AppDbContext>()); s.AddHttpContextAccessor(); s.AddScoped<ICurrentUserService,CurrentUserService>(); s.AddScoped<TokenService>(); s.AddIdentityCore<AppUser>().AddRoles<IdentityRole>().AddEntityFrameworkStores<AppDbContext>().AddDefaultTokenProviders(); var key=Encoding.UTF8.GetBytes(c["Jwt:Key"]!); s.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ValidIssuer=c["Jwt:Issuer"],ValidAudience=c["Jwt:Audience"],IssuerSigningKey=new SymmetricSecurityKey(key)}); s.AddAuthorization(); return s; } }
